 private final UiKit.Palette p=new UiKit.Palette(true);private RunStore store;private Bundle drafts=new Bundle();private LinearLayout body;private TextView status;private String screen;private LocalDate race=LocalDate.now().plusWeeks(12);private final ExecutorService worker=Executors.newSingleThreadExecutor();
 public void onCreate(Bundle state){super.onCreate(state);store=new RunStore(this);screen=getIntent().getStringExtra("screen");if(screen==null)screen="hub";if(state!=null){race=LocalDate.parse(state.getString("race",race.toString()));screen=state.getString("screen",screen);drafts=state.getBundle("drafts");if(drafts==null)drafts=new Bundle();}show();}protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putString("race",race.toString());out.putString("screen",screen);out.putBundle("drafts",drafts);}protected void onDestroy(){worker.shutdown();super.onDestroy();}
 private int dp(int n){return UiKit.dp(this,n);}private TextView text(String s,int size){TextView v=UiKit.label(this,s,size,size>=18?p.ink:p.muted,size>=20);body.addView(v);return v;}private void action(String label,Runnable r){body.addView(UiKit.action(this,p,label,()->{try{r.run();}catch(Exception e){status.setText(UserErrors.message(e));}}));}
 private Button quietAction(String label,boolean danger,Runnable operation){return UiKit.quietAction(this,p,label,danger,()->{try{operation.run();}catch(Exception error){status.setText(UserErrors.message(error));}});}
 private TextView cardText(LinearLayout card,String value,int size,boolean medium){TextView label=UiKit.label(this,value,size,medium?p.ink:p.muted,medium);card.addView(label);return label;}
 private LinearLayout card(){LinearLayout card=UiKit.card(this,p);body.addView(card);return card;}
 private EditText input(String label,String value){text(label,14);EditText e=new EditText(this);e.setTextColor(p.ink);e.setText(drafts.getString(label,value));e.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void afterTextChanged(android.text.Editable e){}public void onTextChanged(CharSequence s,int a,int b,int c){drafts.putString(label,s.toString());}});e.setInputType(8194);e.setContentDescription(label);body.addView(e);return e;}private CheckBox check(String label,boolean on){CheckBox b=new CheckBox(this);b.setText(label);b.setTextColor(p.ink);b.setMinHeight(dp(48));b.setChecked(drafts.getBoolean(label,on));b.setOnCheckedChangeListener((v,checked)->drafts.putBoolean(label,checked));body.addView(b);return b;}private Spinner choice(String label,List<String> items,int selected){text(label,14);Spinner v=new Spinner(this);v.setMinimumHeight(dp(48));v.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,items));v.setSelection(Math.max(0,drafts.getInt(label,selected)));v.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> parent,View view,int pos,long id){drafts.putInt(label,pos);}public void onNothingSelected(AdapterView<?> parent){}});body.addView(v);return v;}
 private Switch toggle(LinearLayout parent,String label,boolean on){Switch control=new Switch(this);control.setText(label);control.setTextColor(p.ink);control.setTextSize(16);control.setMinHeight(dp(56));control.setChecked(drafts.getBoolean(label,on));control.setOnCheckedChangeListener((v,checked)->drafts.putBoolean(label,checked));parent.addView(control);return control;}
 private CheckBox dayChip(String label,boolean on){CheckBox chip=new CheckBox(this);chip.setButtonDrawable((android.graphics.drawable.Drawable)null);chip.setText(label.substring(0,3));chip.setTextSize(14);chip.setTextColor(p.ink);chip.setGravity(Gravity.CENTER);chip.setMinHeight(dp(48));chip.setPadding(dp(6),dp(8),dp(6),dp(8));chip.setContentDescription(label);chip.setChecked(drafts.getBoolean(label,on));Runnable style=()->{var background=UiKit.shape(this,chip.isChecked()?p.tonal:p.background,12);background.setStroke(dp(1),chip.isChecked()?p.primary:p.outline);chip.setBackground(background);chip.setTextColor(chip.isChecked()?p.primary:p.muted);};chip.setOnCheckedChangeListener((v,checked)->{drafts.putBoolean(label,checked);style.run();});style.run();return chip;}
 private void show(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(p.background);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i.consumeSystemWindowInsets();});LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(dp(8),0,dp(12),0);bar.addView(UiKit.iconButton(this,p,R.drawable.ic_arrow_back,"Back",this::finish),new LinearLayout.LayoutParams(dp(48),dp(48)));bar.addView(UiKit.label(this,switch(screen){case "reminders"->"Movement & run reminders";case "week"->"My week changed";case "race"->"Plan for a race date";case "checkin"->"Before you move";case "review"->"Workout review";case "indoorHistory"->"Indoor progress";default->"Keep improving";},18,p.ink,true));root.addView(bar);ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(20),dp(4),dp(20),dp(24));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);status=UiKit.status(this,p);try{switch(screen){case "reminders"->reminders();case "week"->week();case "race"->race();case "checkin"->checkin();case "review"->review();case "indoorHistory"->indoorHistory();default->hub();}}catch(Exception e){status.setText(UserErrors.message(e));}body.addView(status);}
 private void navigate(String value){screen=value;show();}private void hub(){text("Build a repeatable week.",26);text("Focus on movement, consistency and useful feedback. No badges or invented readiness score.",16);action("Start walking pad / treadmill",()->startActivity(new Intent(this,IndoorActivity.class)));action("Movement & run reminders",()->navigate("reminders"));action("Quick pre-session check-in",()->navigate("checkin"));action("My week changed",()->navigate("week"));action("Plan for a race date",()->navigate("race"));action("Indoor progress",()->navigate("indoorHistory"));action("Match & review saved workouts",()->{screen="review";show();});}
 private void checkin(){action("Open recovery check-in",()->startActivity(new Intent(this,DailyHealthActivity.class).putExtra("screen","checkin")));text("Review sleep, fatigue, soreness, illness and alcohol locally. Your plan only changes after review.",15);}
 private void reminders()throws Exception{text("Reminder schedule",25);TextView intro=text("Choose when OpenRun can nudge you. Android controls exact delivery time, and active recordings or training holds suppress prompts.",14);intro.setTextColor(p.muted);body.addView(UiKit.choice(this,p,"Movement detection & recovery",()->startActivity(new Intent(this,DailyHealthActivity.class).putExtra("screen","movement"))));if(new DailyHealthStore(this).settings().movement())text("Health Connect movement detection is enabled. Fixed-time movement prompts stay suppressed; planned workout reminders are unchanged.",14);JSONObject r=store.v103().optJSONObject("reminders");if(r==null)r=V103Data.reminderDefaults();ReminderPlan cfg=V103Data.plan(r);LinearLayout types=card();cardText(types,"REMIND ME ABOUT",12,false);Switch movement=toggle(types,"Movement break reminders",cfg.movement()),workouts=toggle(types,"Planned workout reminder",cfg.workouts());LinearLayout daysCard=card();cardText(daysCard,"ACTIVE DAYS",12,false);List<CheckBox> weekdays=new ArrayList<>();LinearLayout dayRow=null;for(DayOfWeek day:DayOfWeek.values()){if(weekdays.size()%4==0){dayRow=new LinearLayout(this);dayRow.setOrientation(LinearLayout.HORIZONTAL);dayRow.setBaselineAligned(false);daysCard.addView(dayRow);}CheckBox dayControl=dayChip(day.toString(),cfg.days().contains(day.getValue()));weekdays.add(dayControl);LinearLayout.LayoutParams dayParams=new LinearLayout.LayoutParams(0,-2,1);dayParams.setMargins(dp(3),dp(3),dp(3),dp(3));dayRow.addView(dayControl,dayParams);}LinearLayout schedule=card();cardText(schedule,"TIMES",12,false);LinearLayout page=body;body=schedule;EditText start=input("Movement window starts · hour 0–23",""+cfg.start()/60),end=input("Movement window ends · hour 1–24",""+cfg.end()/60);Spinner interval=choice("Minutes between movement prompts",List.of("30","60","90","120","180"),List.of(30,60,90,120,180).indexOf(cfg.interval()));EditText workoutHour=input("Workout reminder · hour 0–23",""+cfg.workoutMinute()/60),workoutMinute=input("Workout reminder · minute 0–59",""+cfg.workoutMinute()%60);body=page;
  action("Save reminder preferences",()->{try{int begin=Integer.parseInt(start.getText().toString())*60,finish=Integer.parseInt(end.getText().toString())*60,hour=Integer.parseInt(workoutHour.getText().toString()),minute=Integer.parseInt(workoutMinute.getText().toString());if(hour<0||hour>23||minute<0||minute>59)throw new IllegalArgumentException("Enter a valid reminder time");Set<Integer> days=new HashSet<>();for(int i=0;i<weekdays.size();i++)if(weekdays.get(i).isChecked())days.add(i+1);ReminderPlan next=new ReminderPlan(movement.isChecked(),workouts.isChecked(),days,begin,finish,Integer.parseInt(interval.getSelectedItem().toString()),hour*60+minute);JSONObject value=new JSONObject().put("movement",next.movement()).put("workouts",next.workouts()).put("days",new JSONArray(days)).put("start",begin).put("end",finish).put("interval",next.interval()).put("workoutMinute",next.workoutMinute());synchronized(RunStore.LOCK){JSONObject d=store.v103();d.put("reminders",value);store.v103(d);}Reminders.schedule(this);if((next.movement()||next.workouts())&&Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},103);else status.setText(next.movement()||next.workouts()?"Preferences saved. Delivery is approximate; check notification permission and channels below.":"Reminders are off; pending alarms cancelled.");}catch(Exception e){status.setText(UserErrors.message(e));}});
  TextView notification=text("Notifications are "+(Reminders.allowed(this)?"allowed":"blocked")+" at app level. Individual channels can still be disabled in Android Settings.",13);notification.setTextColor(p.muted);body.addView(quietAction("Open OpenRun notification settings",false,()->startActivity(new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName()))));body.addView(quietAction("Send a test reminder now",false,()->{if(!Reminders.allowed(this))throw new IllegalStateException("Allow notifications in Android Settings first");Reminders.channels(this);getSystemService(NotificationManager.class).notify(1044,new Notification.Builder(this,"movement").setSmallIcon(R.drawable.ic_directions_run).setContentTitle("OpenRun · test movement reminder").setContentText("A short walking-pad break can fit here. This is a test, not inactivity detection.").setAutoCancel(true).setContentIntent(Reminders.open(this,"indoor",1044)).build());status.setText("Test requested. If absent, check the Movement breaks notification channel.");}));
 }
 public void onRequestPermissionsResult(int code,String[] permissions,int[] result){super.onRequestPermissionsResult(code,permissions,result);if(code==103){Reminders.schedule(this);status.setText(Reminders.allowed(this)?"Notifications allowed. You can send a test reminder.":"Reminder preferences are saved, but notifications remain blocked. Open notification settings to enable them.");}}
 private void week(){if(store.config()==null){text("Create a running plan first.",18);return;}text("What can fit this week?",25);text("Select available days from today through Sunday. Only remaining sessions are considered; missed days are not added as catch-up. Review every proposed move or skip before applying.",15);LocalDate today=LocalDate.now(),end=today.with(DayOfWeek.SUNDAY);Map<LocalDate,CheckBox> boxes=new LinkedHashMap<>();for(LocalDate d=today;!d.isAfter(end);d=d.plusDays(1))boxes.put(d,check(d.format(DateTimeFormatter.ofPattern("EEE, d MMM")),true));action("Preview balanced week",()->preview(boxes,false));action("Preview lighter week",()->preview(boxes,true));text("If no suitable slot exists, a session is proposed as skipped. These are transparent scheduling rules, not a validated combined-load or injury assessment.",13);}
 private void preview(Map<LocalDate,CheckBox> boxes,boolean lighter){if(store.resting())throw new IllegalStateException("Review your training hold first");Set<LocalDate> slots=new HashSet<>();boxes.forEach((d,b)->{if(b.isChecked())slots.add(d);});LocalDate now=LocalDate.now(),end=now.with(DayOfWeek.SUNDAY);List<PlanEngine.Session> pending=store.plannedSessions().stream().filter(s->!s.date().isBefore(now)&&!s.date().isAfter(end)&&!store.completed(store.planId()+":"+s.id())&&!store.skipped(store.planId()+":"+s.id())).collect(java.util.stream.Collectors.toList());if(pending.isEmpty())throw new IllegalStateException("No remaining workouts this week to change");for(var s:store.plannedSessions())if(store.completed(store.planId()+":"+s.id()))slots.remove(s.date());String fingerprint=store.proposalFingerprint();var proposed=ScheduleProposer.propose(pending,slots,store.otherActivities(),lighter);String out=store.previewProposal(fingerprint,proposed,"");new AlertDialog.Builder(this).setTitle("Review proposed week").setMessage(out.toString()).setNegativeButton("Keep current week",null).setPositiveButton("Apply these changes",(d,w)->{try{store.applyProposal(fingerprint,proposed);Reminders.schedule(this);WorkoutWidget.updateAll(this);status.setText("Reviewed changes saved. History is kept; no catch-up mileage added.");}catch(Exception e){status.setText(UserErrors.message(e));}}).show();}
 private void race(){startActivity(new Intent(this,RacePlanActivity.class));finish();}
 private void indoorHistory()throws Exception{JSONArray rows=store.v103().optJSONArray("indoor");text("Indoor movement",25);if(rows==null||rows.length()==0){LinearLayout empty=card();cardText(empty,"Your first indoor session starts here",20,true);cardText(empty,"Walking stays separate from running mileage. Record with phone steps or enter the machine distance when you finish.",14,false);empty.addView(UiKit.action(this,p,"Start walking pad / treadmill",()->startActivity(new Intent(this,IndoorActivity.class))));return;}long walk=0,run=0;Set<String> activeDays=new HashSet<>();for(int i=0;i<rows.length();i++){var r=rows.getJSONObject(i);LocalDate date=LocalDate.parse(r.getString("date"));if(!date.isBefore(LocalDate.now().minusDays(6))&&!date.isAfter(LocalDate.now())){if(r.getString("kind").equals("Walk"))walk+=r.getLong("seconds");else run+=r.getLong("seconds");activeDays.add(date.toString());}}LinearLayout summary=card();cardText(summary,"LAST 7 DAYS",12,false);cardText(summary,walk/60+" min walking",20,true);cardText(summary,run/60+" min indoor running",16,false);cardText(summary,activeDays.size()+" active "+(activeDays.size()==1?"day":"days"),16,false);TextView note=text("Walking is kept separate from running mileage. Indoor distance is machine-entered or clearly labelled as a phone-step estimate — never GPS.",13);note.setTextColor(p.muted);for(int i=rows.length()-1;i>=0;i--){var r=rows.getJSONObject(i);LinearLayout session=card();cardText(session,r.getString("kind")+" · "+LocalDate.parse(r.getString("date")).format(DateTimeFormatter.ofPattern("d MMM yyyy")),19,true);cardText(session,r.getLong("seconds")/60+"m "+r.getLong("seconds")%60+"s"+(r.isNull("km")?" · time only":String.format(Locale.ROOT," · %.2f km",r.getDouble("km"))),18,true);cardText(session,r.optString("distanceSource","Machine entered")+" · effort "+r.getInt("effort")+"/10",14,false);if(r.optLong("phoneSteps")>0)cardText(session,String.format(Locale.ROOT,"%,d detected phone steps%s",r.optLong("phoneSteps"),r.optBoolean("partialSteps")?" · may be partial":""),14,false);if(!r.optString("planned").isEmpty())cardText(session,"Workout steps confirmed: "+r.optInt("stepsDone")+" · matching requires review",13,false);String indoorId=r.getString("id");if(store.runs().stream().anyMatch(saved->saved.sessionId().equals("indoor:"+indoorId)))session.addView(UiKit.action(this,p,"Review this indoor run",()->{getIntent().putExtra("id","indoor:"+indoorId);navigate("review");}));else session.addView(quietAction("Delete this indoor entry",true,()->new AlertDialog.Builder(this).setTitle("Delete indoor entry permanently?").setMessage("This removes this time-only or walking entry from local history. It cannot be undone.").setNegativeButton("Keep",null).setPositiveButton("Delete",(d,w)->{store.deleteIndoorTimeOnly(indoorId);show();}).show()));}}
 private void review()throws Exception{String id=getIntent().getStringExtra("id");RunStore.Run selected=null;for(var r:store.runs())if(r.sessionId().equals(id))selected=r;if(selected==null){text("Choose a saved workout",25);for(var r:store.runs())action(r.date()+" · "+PlanEngine.distance(r.km())+" · "+r.source(),()->{getIntent().putExtra("id",r.sessionId());show();});if(store.runs().isEmpty())text("Record or import a running activity first. Time-only indoor sessions appear in Indoor progress.",16);return;}RunStore.Run r=selected;text(r.date()+" · "+r.workoutType(),25);text(PlanEngine.distance(r.km())+" · "+r.seconds()/60+"m "+r.seconds()%60+"s · "+r.source(),18);text("Duration semantics depend on the source: GPS/indoor timers exclude pauses; imported elapsed time may include them.",13);text("Interval evidence: "+(r.qualitySeconds()>0?r.qualitySeconds()+" quality seconds over "+PlanEngine.distance(r.qualityKm()):"No verified completed quality-set metrics for this activity."),15);
  JSONObject matches=store.v103().optJSONObject("matches");String matched=matches==null?"":matches.optString(r.sessionId());List<PlanEngine.Session> pending=store.plannedSessions().stream().filter(s->!store.completed(store.planId()+":"+s.id())&&!store.skipped(store.planId()+":"+s.id())).collect(java.util.stream.Collectors.toList());List<PlanEngine.Session> candidates=WorkoutMatcher.candidates(LocalDate.parse(r.date()),r.km(),pending);String direct=r.sessionId().startsWith(store.planId()+":")?r.sessionId():matched;
  if(!direct.isEmpty()){for(var s:store.plannedSessions())if((store.planId()+":"+s.id()).equals(direct))text(String.format(Locale.ROOT,"Planned %.1f km · actual %.2f km · difference %+.2f km",s.km(),r.km(),r.km()-s.km()),17);if(!matched.isEmpty())action("Unmatch planned workout",()->{store.unmatch(r.sessionId());Reminders.schedule(this);show();});}
  else{for(var s:candidates)action("Match to "+s.date()+" · "+s.title()+" · "+PlanEngine.distance(s.km()),()->new AlertDialog.Builder(this).setTitle("Complete this planned workout?").setMessage("Links this saved activity to the selected workout without creating a second run. Totals stay unchanged. You can unmatch it later.").setNegativeButton("Cancel",null).setPositiveButton("Confirm match",(d,w)->{try{store.matchWorkout(r.sessionId(),store.planId()+":"+s.id());Reminders.schedule(this);show();}catch(Exception e){status.setText(UserErrors.message(e));}}).show());if(candidates.isEmpty())text("No nearby uncompleted workout matches the date/distance suggestion range. No completion was inferred.",14);}
  for(var other:store.runs())if(!other.sessionId().equals(r.sessionId())&&WorkoutMatcher.possibleDuplicate(LocalDate.parse(r.date()),r.km(),r.seconds(),LocalDate.parse(other.date()),other.km(),other.seconds()))text("Possible duplicate: "+other.source()+" · "+other.date()+" · "+PlanEngine.distance(other.km())+". Compare in Progress before deleting either record; no automatic merge.",15);
  if(!r.routeFile().isEmpty()){TextView splits=text("Calculating recorded kilometre splits…",16);worker.submit(()->{try{var points=TrackingService.readRoute(this,r.routeFile()).stream().map(s->new BestEfforts.Fix(s.lat(),s.lon(),s.time(),s.segment())).collect(java.util.stream.Collectors.toList());var result=WorkoutReview.splits(points);StringBuilder value=new StringBuilder();for(var split:result)value.append("Km ").append(split.kilometre()).append(" · ").append(PaceProfile.format(split.seconds())).append("\n");value.append(WorkoutReview.consistency(result));runOnUiThread(()->{if(!isDestroyed())splits.setText(value);});}catch(Exception e){runOnUiThread(()->{if(!isDestroyed())splits.setText("Saved route could not be read; totals are retained.");});}});}else text("No GPS route: kilometre splits and pace consistency cannot be reconstructed from totals alone.",14);
  action("Correct distance / recorded duration",()->correct(r));
 }
 private void correct(RunStore.Run r){LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(20),0,dp(20),0);EditText km=new EditText(this),sec=new EditText(this);km.setHint("Distance km");km.setInputType(8194);km.setText(""+r.km());sec.setHint("Duration seconds");sec.setInputType(2);sec.setText(""+r.seconds());form.addView(km);form.addView(sec);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Correct totals").setMessage("This changes saved totals only. It does not rewrite GPS routes or external services. Previous quality-set evidence is cleared. Feedback and pain holds remain.").setView(form).setNegativeButton("Cancel",null).setPositiveButton("Save correction",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{try{store.correctTotals(r.sessionId(),Double.parseDouble(km.getText().toString()),Long.parseLong(sec.getText().toString()));dialog.dismiss();show();}catch(Exception e){Toast.makeText(this,UserErrors.message(e),Toast.LENGTH_LONG).show();}}));dialog.show();}
